#[test]
fn sixpack_and_reports() {
    let d: Vec<f64> = CAP_DATA.to_vec();
    let s = capability_sixpack_individuals(&d, &spec(), &SixpackOptions::default()).unwrap();
    let panels = s.charts();
    assert_eq!(panels.len(), 6);
    let r = s.to_report("Sixpack");
    r.validate().unwrap();
    assert_eq!(r.charts().len(), 6);
    let text = r.render_text();
    for key in [
        "Process Data",
        "Potential (Within) Capability",
        "Overall Capability",
        "Expected Performance (Overall)",
        "Observed Performance",
        "Control Limits",
    ] {
        assert!(text.contains(key), "missing {key}");
    }
    let back = SessionReport::from_json(&r.to_json()).unwrap();
    assert_eq!(back.to_json(), r.to_json()); // NaN-safe comparison
                                             // Control charts and capability variants render and validate too.
    let imr = i_mr(IMR_DATA, &ChartOptions { tests: SpecialCauseTests::all(), ..Default::default() }).unwrap();
    let rep = imr.to_report("I-MR");
    rep.validate().unwrap();
    assert!(rep.render_text().contains("Test failed at points"));
    for rep in [
        p_chart(&OJ, &[50.0; 30], &ChartOptions::default()).unwrap().to_report("p"),
        xbar_r(&sg(), &ChartOptions::default()).unwrap().to_report("xr"),
        capability_distribution(WB_DATA, Family::Weibull, None, &Specs::two_sided(2.0, 45.0))
            .unwrap()
            .to_report("weibull"),
        capability_transformed_individuals(
            BC_DATA,
            &Transformation::BoxCox(BoxCox::fit(BC_DATA, LambdaChoice::Rounded).unwrap()),
            &Specs::two_sided(0.5, 40.0),
            &CapabilityOptions::default(),
        )
        .unwrap()
        .to_report("bc"),
    ] {
        rep.validate().unwrap();
        assert_eq!(SessionReport::from_json(&rep.to_json()).unwrap().to_json(), rep.to_json());
    }
    let t = openstats_stats::spc::constants_section(2, 25).unwrap();
    assert_eq!(t.blocks.len(), 1);
    assert!(openstats_stats::spc::constants_section(1, 5).is_err());
}

#[test]
fn error_handling() {
    assert!(i_mr(&[1.0, f64::INFINITY, 2.0], &ChartOptions::default()).is_err());
    assert!(xbar_r(&[vec![1.0, 2.0], vec![3.0]], &ChartOptions::default()).is_err());
    assert!(xbar_r(&[vec![1.0; 30], vec![2.0; 30]], &ChartOptions::default()).is_err()); // n > 25 has no d2 table
    assert!(capability_individuals(CAP_DATA, &Specs::default(), &CapabilityOptions::default()).is_err());
    assert!(capability_individuals(CAP_DATA, &Specs::two_sided(10.0, 5.0), &CapabilityOptions::default()).is_err());
    assert!(fit_distribution(&[-1.0, 2.0, 3.0, 4.0], Family::Weibull, None).is_err());
    let gam = Gamma::new(2.0, 1.0, 0.0).unwrap();
    let _ = gam.cdf(1.0);
}
